// EDIT THIS VALUE. Secrets belong in n8n credentials, never here.
const SETTINGS = {
  supabaseUrl: 'https://YOUR_PROJECT_REF.supabase.co',
};
const input = $input.first().json || {};
const fail = (code, error) => [{ json: { ok: false, code, error } }];
const reportId = input.report_id;
const dataset = input.dataset;
const traceId = input.trace_id;
let revision = input.revision;
if (typeof revision === 'string' && /^\d+$/.test(revision.trim())) revision = Number(revision);
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof reportId !== 'string' || !uuidRe.test(reportId)) {
  return fail('INVALID_REQUEST', 'report_id must be a UUID.');
}
if (!Number.isSafeInteger(revision) || revision < 1) {
  return fail('INVALID_REQUEST', 'revision must be a positive integer.');
}
if (dataset !== 'live' && dataset !== 'demo') {
  return fail('INVALID_REQUEST', 'dataset must be live or demo.');
}
if (typeof traceId !== 'string' || traceId.trim() === '' || traceId.length > 200) {
  return fail('INVALID_REQUEST', 'trace_id must be a non-empty string of at most 200 characters.');
}
const supabaseUrl = String(SETTINGS.supabaseUrl || '').replace(/\/+$/, '');
if (!/^https?:\/\/[a-z0-9.-]+(?::\d{1,5})?$/i.test(supabaseUrl) || supabaseUrl.includes('YOUR_PROJECT_REF')) {
  return fail('DEPENDENCY_ERROR', 'Set your Supabase Project URL in Settings and Validation before running.');
}
return [{ json: {
  ok: true,
  supabase_url: supabaseUrl,
  service_id: 'website',
  report_id: reportId,
  revision,
  dataset,
  trace_id: traceId,
} }];

const settings = $('Settings and Validation').first().json;
const fail = (code, error) => [{ json: { ok: false, code, error } }];
function rowsFromFullResponse(raw) {
  if (raw == null) return null;
  let body = Object.prototype.hasOwnProperty.call(raw, 'body') ? raw.body : raw;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { return null; }
  }
  if (Array.isArray(body)) return body;
  return null;
}
const rows = rowsFromFullResponse($input.first().json);
if (rows === null) return fail('DEPENDENCY_ERROR', 'Unexpected response shape from Load Saved Report.');
if (rows.length === 0) return fail('REPORT_NOT_FOUND', 'No saved report matched report_id, service website, and dataset.');
if (rows.length !== 1) return fail('DEPENDENCY_ERROR', 'Unexpected response shape from Load Saved Report.');
const row = rows[0];
if (!row || typeof row !== 'object' || typeof row.id !== 'string') {
  return fail('DEPENDENCY_ERROR', 'Unexpected response shape from Load Saved Report.');
}
if (row.id !== settings.report_id) {
  return fail('DEPENDENCY_ERROR', 'Returned report id did not match the request.');
}
if (Number(row.revision) !== Number(settings.revision)) {
  return fail('STALE_REPORT', 'Saved revision does not match the requested revision.');
}
const report = row.report;
if (!report || typeof report !== 'object' || Array.isArray(report)) {
  return fail('DEPENDENCY_ERROR', 'Saved report JSON is missing or invalid.');
}
if (!(report.is_final === true && report.unknown_seconds === 0 && report.assessment === 'breach_detected')) {
  return fail('NOT_ELIGIBLE', 'Report is not a completed, fully covered breach_detected assessment.');
}
const snap = report.contract_snapshot;
const creditPct = report.candidate_credit_pct;
const creditAmount = report.candidate_credit_amount;
const currency = report.currency;
if (!snap || typeof snap !== 'object' || Array.isArray(snap) || creditPct == null || creditAmount == null || typeof currency !== 'string' || !currency) {
  return fail('DEPENDENCY_ERROR', 'Missing contract_snapshot or credit values on the saved report.');
}
if (snap.provider_name == null || snap.name == null || snap.contract_reference == null || snap.monthly_fee == null || snap.credit_pct == null || snap.sla_target_pct == null) {
  return fail('DEPENDENCY_ERROR', 'Missing contract_snapshot or credit values on the saved report.');
}
const downSeconds = Number(report.down_seconds);
const availability = report.estimated_monthly_availability_pct;
if (!Number.isFinite(downSeconds) || downSeconds < 0 || availability == null) {
  return fail('DEPENDENCY_ERROR', 'Missing downtime or availability values on the saved report.');
}
const minutesText = String(Number((downSeconds / 60).toFixed(3)));
const money = (n) => Number(n).toFixed(2);
const lines = ['SLA GUARD CLAIM DRAFT'];
if (settings.dataset === 'demo') lines.push('DEMO ONLY - SYNTHETIC EVIDENCE');
lines.push('Status: DRAFT FOR HUMAN REVIEW - NOT SUBMITTED');
lines.push('Provider: ' + snap.provider_name);
lines.push('Service: ' + snap.name);
lines.push('Billing month (UTC): ' + report.month);
lines.push('Contract reference: ' + snap.contract_reference);
lines.push('Estimated downtime: ' + minutesText + ' minutes (' + downSeconds + ' seconds)');
lines.push('Observed uptime: ' + availability + '% against SLA target ' + snap.sla_target_pct + '%');
lines.push('Evidence: report ID ' + row.id + ', revision ' + row.revision + ', dataset ' + settings.dataset);
lines.push('Credit basis: monthly fee ' + money(snap.monthly_fee) + ' ' + currency + '; credit rate ' + snap.credit_pct + '%');
lines.push('Candidate service credit: ' + creditPct + '% = ' + money(creditAmount) + ' ' + currency);
lines.push('Review notes: These are polling estimates from one monitoring location. Provider responsibility, contractual exclusions, maintenance, and any claim deadline require human verification. This draft has not been submitted.');
if (settings.dataset === 'demo') {
  lines.push('SYNTHETIC DATA. The credit is an example and must never be submitted as a real claim.');
}
return [{ json: {
  ok: true,
  supabase_url: settings.supabase_url,
  report_id: row.id,
  revision: Number(row.revision),
  dataset: settings.dataset,
  claim_draft: lines.join('\n'),
} }];

const expected = $('Evaluate Saved Report').first().json;
const fail = (code, error) => [{ json: { ok: false, code, error } }];
function rowsFromFullResponse(raw) {
  if (raw == null) return null;
  let body = Object.prototype.hasOwnProperty.call(raw, 'body') ? raw.body : raw;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { return null; }
  }
  if (Array.isArray(body)) return body;
  return null;
}
const rows = rowsFromFullResponse($input.first().json);
if (rows === null) return fail('DEPENDENCY_ERROR', 'Unexpected response shape from Save Claim Draft.');
if (rows.length === 0) return fail('STALE_REPORT', 'No row updated; a newer revision cannot be overwritten.');
if (rows.length !== 1) return fail('DEPENDENCY_ERROR', 'Unexpected response shape from Save Claim Draft.');
const row = rows[0];
if (!row || typeof row !== 'object') {
  return fail('DEPENDENCY_ERROR', 'Unexpected response shape from Save Claim Draft.');
}
if (row.id !== expected.report_id || Number(row.revision) !== Number(expected.revision) || row.claim_draft !== expected.claim_draft) {
  return fail('DEPENDENCY_ERROR', 'Returned saved row did not match the claim draft that was sent.');
}
return [{ json: {
  ok: true,
  report_id: row.id,
  revision: Number(row.revision),
  claim_draft: row.claim_draft,
} }];

const input = $input.first().json;
return [{ json: {
  ok: true,
  result: {
    report_id: input.report_id,
    revision: input.revision,
    claim_draft: input.claim_draft,
  },
} }];

const input = $input.first().json || {};
const allowed = ['INVALID_REQUEST', 'REPORT_NOT_FOUND', 'STALE_REPORT', 'NOT_ELIGIBLE', 'DEPENDENCY_ERROR'];
if (input.ok === false && allowed.includes(input.code)) {
  return [{ json: { ok: false, code: input.code, error: String(input.error) } }];
}
const raw = input.error && typeof input.error === 'object'
  ? (input.error.message || JSON.stringify(input.error))
  : (input.error || input.message || JSON.stringify(input));
return [{ json: {
  ok: false,
  code: 'DEPENDENCY_ERROR',
  error: String(raw).slice(0, 500),
} }];
